package cl.bolsillo.app;
import android.widget.*;import org.json.*;import java.time.*;import java.util.*;
/** Daily work payments are ordinary income transactions, so balances and backups stay consistent. */
final class WorkScreen {
 static boolean matches(JSONObject data,JSONObject t)throws Exception{if(!t.optString("type").equals("income")||!t.optString("status").equals("posted"))return false;if(t.optBoolean("workPayment"))return true;JSONObject cat=Ledger.find(data.getJSONArray("categories"),t.optString("category"));return cat!=null&&BankNotificationParser.normalize(cat.optString("name")).equals("trabajo");}
 static List<JSONObject> payments(JSONObject data)throws Exception{List<JSONObject> result=new ArrayList<>();JSONArray tx=data.getJSONArray("transactions");for(int i=0;i<tx.length();i++){JSONObject t=tx.getJSONObject(i);if(matches(data,t))result.add(t);}result.sort((x,y)->y.optString("date").compareTo(x.optString("date")));return result;}
 static void show(MainActivity a)throws Exception{LinearLayout tabs=Modern.row(a);for(String name:Arrays.asList("Resumen","Pagos")){TextView p=Glass.pill(a,name,a.workView.equals(name));tabs.addView(p,new LinearLayout.LayoutParams(0,a.dp(48),1));Modern.press(p,()->{a.workView=name;a.workPage=0;a.render();});}Modern.add(a.body,tabs,8);a.swipePages(()->{a.workView="Pagos";a.render();},()->{a.workView="Resumen";a.render();});List<JSONObject> all=payments(a.data);if(a.workView.equals("Pagos")){history(a,all);return;}String current=a.workMonth;LinearLayout period=Modern.row(a);android.view.View previous=Modern.iconButton(a,"back","Mes anterior",()->{a.workMonth=java.time.YearMonth.parse(current).minusMonths(1).toString();a.render();}),next=Modern.iconButton(a,"chevron","Mes siguiente",()->{a.workMonth=java.time.YearMonth.parse(current).plusMonths(1).toString();a.render();});TextView label=Modern.text(a,java.time.YearMonth.parse(current).format(java.time.format.DateTimeFormatter.ofPattern("MMMM yyyy",Locale.forLanguageTag("es-CL"))),18,Glass.ink(a),true);label.setGravity(android.view.Gravity.CENTER);period.addView(previous,new LinearLayout.LayoutParams(a.dp(52),a.dp(48)));period.addView(label,new LinearLayout.LayoutParams(0,a.dp(48),1));period.addView(next,new LinearLayout.LayoutParams(a.dp(52),a.dp(48)));previous.setContentDescription("Mes anterior");next.setContentDescription("Mes siguiente");next.setEnabled(current.compareTo(Ledger.today().substring(0,7))<0);next.setAlpha(next.isEnabled()?1:.35f);Modern.add(a.body,period,10);long month=0,hourlyAmount=0;int days=0;Set<String> dates=new HashSet<>();double hours=0;for(JSONObject t:all)if(t.optString("date").startsWith(current)){month=Math.addExact(month,t.optLong("amount"));dates.add(t.optString("date"));hours+=t.optDouble("workHours",0);if(t.optDouble("workHours",0)>0)hourlyAmount=Math.addExact(hourlyAmount,t.optLong("amount"));}days=dates.size();Modern.add(a.body,Modern.stat(a,"income","Cobrado",a.money(month),Glass.MINT),4);Modern.pair(a,Modern.stat(a,"calendar","Días pagados",String.valueOf(days),Glass.BLUE),Modern.stat(a,"chart","Por día",a.money(days==0?0:month/days),Glass.VIOLET));if(hours>0)Modern.add(a.body,Modern.item(a,"activity","Por hora",String.format(Locale.forLanguageTag("es-CL"),"%.1f h registradas",hours),a.money(Math.round(hourlyAmount/hours)),Glass.AMBER,null),10);Modern.add(a.body,Modern.item(a,"plus","Registrar pago diario","Fecha, cuenta y detalle","Añadir",Glass.MINT,()->a.attempt(()->add(a))),12);long[] monthly=new long[6];LocalDate first=LocalDate.parse(current+"-01");for(JSONObject t:all)for(int i=0;i<6;i++)if(t.optString("date").startsWith(first.minusMonths(5-i).toString().substring(0,7)))monthly[i]=Math.addExact(monthly[i],t.optLong("amount"));if(all.isEmpty()){a.caption("Añade tu primer pago para ver la evolución mensual.");return;}Modern.section(a,"Últimos seis meses","",()->{});LinearLayout chart=Modern.surface(a);String[] chartLabels=new String[6];for(int i=0;i<6;i++)chartLabels[i]=first.minusMonths(5-i).format(java.time.format.DateTimeFormatter.ofPattern("MMM yyyy",Locale.forLanguageTag("es-CL")))+" · "+a.money(monthly[i]);chart.addView(new FlowChart(a,monthly,Glass.MINT,chartLabels),new LinearLayout.LayoutParams(-1,a.dp(135)));TextView chartHint=Modern.text(a,"Toca un punto para ver el mes",11,Glass.subtle(a),false);chart.addView(chartHint);Modern.add(a.body,chart,10);Modern.section(a,"Recientes","Ver todos",()->{a.workView="Pagos";a.render();});if(all.isEmpty())a.caption("Registra un pago para empezar a ver tus cifras.");for(int i=0;i<Math.min(3,all.size());i++)row(a,all.get(i));}
 static void history(MainActivity a,List<JSONObject> all)throws Exception{Modern.add(a.body,Modern.item(a,"plus","Nuevo pago","Registro diario","Añadir",Glass.MINT,()->a.attempt(()->add(a))),10);int count=0;String prior="";for(int i=a.workPage*30;i<Math.min(all.size(),(a.workPage+1)*30);i++){JSONObject t=all.get(i);if(!prior.equals(t.optString("date"))){a.caption(MainActivity.shortDate(t.optString("date")));prior=t.optString("date");}row(a,t);count++;}if(count==0)a.caption("Todavía no hay pagos aquí.");if(a.workPage>0)a.action("Anteriores",()->{a.workPage--;a.render();});if(all.size()>(a.workPage+1)*30)a.action("Siguientes",()->{a.workPage++;a.render();});}
 static void row(MainActivity a,JSONObject t){String detail=MainActivity.shortDate(t.optString("date"))+(t.optDouble("workHours",0)>0?" · "+t.optDouble("workHours")+" h":"");Modern.add(a.body,Modern.item(a,"income",t.optString("note").isEmpty()?"Trabajo":t.optString("note"),detail,"+"+a.money(t.optLong("amount")),Glass.MINT,()->Forms.transactionMenu(a,t)),7);}
 static void add(MainActivity a)throws Exception{edit(a,null);}
 static void edit(MainActivity a,JSONObject existing)throws Exception{
  JSONObject old=existing==null?new JSONObject():existing;Forms.Form f=new Forms.Form(a,existing==null?"Pago de trabajo":"Editar pago de trabajo");
  EditText amount=f.field("Monto recibido",old.optString("amount"),true),date=f.field("Fecha",old.optString("date",Ledger.today()),false);
  AutoCompleteTextView client=f.conceptField("Trabajo o cliente",old.optString("note"),"income");Forms.Pick account=new Forms.Pick(f,"Cuenta que recibió el pago","accounts","",old.optString("account"));
  f.advanced();EditText hours=f.field("Horas opcionales",old.optDouble("workHours",0)>0?String.valueOf(old.optDouble("workHours")):"",true),note=f.field("Nota opcional",old.optString("workNote"),false);hours.setInputType(android.text.InputType.TYPE_CLASS_NUMBER|android.text.InputType.TYPE_NUMBER_FLAG_DECIMAL);f.collapseAdvanced("Horas y notas");
  f.save("Guardar pago",()->{long n=Forms.amount(amount,false);String when=LocalDate.parse(Forms.value(date)).toString(),job=Forms.value(client),detail=Forms.value(note);Ledger.require(when.compareTo(Ledger.today())<=0,"Un pago recibido debe tener fecha de hoy o anterior");Ledger.require(job.length()<=80&&detail.length()<=300,"Texto demasiado largo");double h=0;if(!Forms.value(hours).isEmpty()){h=Double.parseDouble(Forms.value(hours).replace(',','.'));Ledger.require(Double.isFinite(h)&&h>0&&h<=24,"Indica entre 0 y 24 horas");}final double worked=h;String accountId=account.id();LocalData.change(a,d->{String category=existing==null?ConceptCatalog.ensureCategory(d,"income","Trabajo").getString("id"):old.getString("category");JSONObject tx=existing==null?NativeSync.transaction("income",n,accountId,"",category,job.isEmpty()?"Trabajo":job,"manual",""):new JSONObject(existing.toString());tx.put("amount",n).put("account",accountId).put("note",job.isEmpty()?"Trabajo":job).put("date",when).put("workPayment",true).put("workHours",worked).put("workNote",detail);JSONArray list=d.getJSONArray("transactions");boolean found=false;for(int i=0;i<list.length();i++)if(list.getJSONObject(i).optString("id").equals(tx.getString("id"))){list.put(i,tx);found=true;break;}if(!found)list.put(tx);});});
 }
}



